theorem thm_GAR : 
  ∃ (a_range : Set ℝ), 
    a_range = {a : ℝ | a > 0 ∧ 
      let f := fun x => (Real.cot x + x) / (1 - x * Real.cot x)
      let A := {x : ℝ | (deriv f) x > 0}
      let B := {x : ℝ | x^2 - 2*a*x + 3 ≤ 0}
      ∃ (s : Finset ℤ), s.card = 2 ∧ ∀ n : ℤ, (n : ℝ) ∈ A ∩ B ↔ n ∈ s} := by

theorem thm_GAR (a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (habc : a * b * c = 1) :
  let first_year := 1 / (a^2 + 2 * b^2 + 3) + 1 / (b^2 + 2 * c^2 + 3) + 1 / (c^2 + 2 * a^2 + 3)
  let second_year := 1 / (a^2 + 2 * b^2 + 4) + 1 / (b^2 + 2 * c^2 + 4) + 1 / (c^2 + 2 * a^2 + 4)
  let percentage_reduction := (first_year - second_year) / first_year * 100
  abs (percentage_reduction - 70) < 10 := by

theorem thm_GAR : 
  let α := Real.arccos (3/5)
  let β := Real.arcsin (3/5)
  let S := ∑' n : ℕ, ∑' m : ℕ, (Real.cos (α * (n : ℝ) + β * (m : ℝ))) / ((2 : ℝ)^n * (3 : ℝ)^m)
  let P := fun (x y : ℤ) => (x : ℝ)^5 + 3*(x : ℝ)^4*(y : ℝ) - 5*(x : ℝ)^3*(y : ℝ)^2 - 15*(x : ℝ)^2*(y : ℝ)^3 + 4*(x : ℝ)*(y : ℝ)^4 + 12*(y : ℝ)^5
  (∀ x y : ℤ, P x y ≠ S) ∧ (∃ S_val : ℝ, S = S_val) := by

